using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1InteriorVisual {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_InteriorRedesign/";static string O=>R+"/Docs/Review/2026-11-12_B1_Interior/";static List<object> facts=new List<object>();
 static Vector3 V(JToken q)=>new Vector3((float)q[0],(float)q[1],(float)q[2]);
 static bool culled=false;static string prefix="";
 static bool Free(Vector3 p)=>!Physics.CheckCapsule(p+Vector3.up*.43f,p+Vector3.up*1.5f,.32f,~0,QueryTriggerInteraction.Ignore);
 static Vector3 Stand(Vector3 p){if(Free(p))return p;for(float r=.1f;r<=.7f;r+=.1f)for(int a=0;a<360;a+=15){var q=p+new Vector3(Mathf.Cos(a*Mathf.Deg2Rad),0,Mathf.Sin(a*Mathf.Deg2Rad))*r;if(Free(q))return q;}throw new Exception("No standing camera at "+p);}
 static void Shot(string name,Vector3 pos,Vector3 target){var g=new GameObject("InteriorReviewCamera");g.hideFlags=HideFlags.HideAndDontSave;var cam=g.AddComponent<Camera>();cam.transform.position=pos;cam.transform.LookAt(target);cam.nearClipPlane=.04f;cam.farClipPlane=350;cam.fieldOfView=82;cam.useOcclusionCulling=culled;cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D t=null;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;t=new Texture2D(1440,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1440,900),0,0);t.Apply();File.WriteAllBytes(O+prefix+name+".jpg",t.EncodeToJPG(90));facts.Add(new{name,position=new[]{pos.x,pos.y,pos.z},target=new[]{target.x,target.y,target.z},eyeHeight=1.7f,realSceneLights=true});}finally{cam.targetTexture=null;RenderTexture.active=old;if(t)UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Capture(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf;player.SetActive(false);Physics.SyncTransforms();facts.Clear();try{
  void Eye(string id,string name,float x,float z,float tx,float tz){var room=plan["rooms"].Single(r=>(string)r["id"]==id);var center=new Vector3((float)room["x"],-18,-(float)room["v"]);var feet=Stand(center+new Vector3(x,0,z));Shot(id+"_"+name,feet+Vector3.up*1.7f,center+new Vector3(tx,1.4f,tz));}
  Eye("C01","reading",0,-1.1f,-2,-4);Eye("C01","comparison",-4,2,0,5);
  Eye("C02","intake",2.8f,1,4.8f,1);Eye("C03","archive",0,-1.4f,0,-4);
  Eye("C04","clinic",0,-1.4f,-2,-3);Eye("C04","waiting",-.5f,1.5f,1.5f,4.2f);
  Eye("C05","meeting",0,-2.4f,0,2.1f);Eye("C05","bypass",4.6f,0,3.8f,3.7f);
  Eye("W01","office",0,-.7f,0,3);Eye("W02","dining",4,3.2f,-1,1);Eye("W02","kitchen",2.5f,-5.2f,-3,-5);
  Eye("W03","vestibule",-1.1f,2.7f,-3.4f,1);Eye("W03","sleep",-3.4f,.9f,-3.5f,-3);Eye("W03","hygiene",0,5.1f,0,7);
  Eye("E01","security",0,-.5f,0,4);Eye("E02","vestibule",-1.4f,.7f,1.6f,2.5f);Eye("E02","archive",3,-1.2f,3,-3);
  Eye("E03","sleep",-3.4f,.9f,-3.5f,-3);Eye("E03","handover",-.7f,3,2,5);
  Eye("N01","analysis",0,-.5f,0,5.5f);Eye("S01","servers",0,-1.4f,3,-3.8f);Eye("S01","backup",0,6.6f,0,4);
  Eye("C01","arrival",0,1.5f,0,-3);Eye("C05","arrival",0,-4.6f,0,0);Eye("W01","arrival",0,-3.2f,0,2);Eye("N01","arrival",0,-4.5f,0,2.5f);Eye("E01","arrival",0,-3,0,2);
 }finally{player.SetActive(active);Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"eye_views.json",JsonConvert.SerializeObject(facts,Formatting.Indented));return new{images=facts.Count};}
 public static object CullingCapture(){culled=true;prefix="culled_";try{return Capture();}finally{culled=false;prefix="";}}
 public static object Sightlines(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var privacy=new List<object>();var seats=new List<object>();
  foreach(string id in new[]{"W03","E03"}){var r=plan["rooms"].Single(q=>(string)q["id"]==id);var c=new Vector3((float)r["x"],-18,-(float)r["v"]);foreach(var d in r["doors"]){var from=c+new Vector3((float)d["x"],1.7f,(float)d["z"]);foreach(var q in plan["placements"].Where(q=>(string)q["room"]==id&&(string)q["model"]=="BL_StaffBunk"))foreach(float y in new[]{.65f,1.8f}){var to=c+V(q["position"])+new Vector3(0,y,0);bool hit=Physics.Linecast(from,to,out var h,~0,QueryTriggerInteraction.Ignore);bool screened=hit&&!h.transform.name.Contains("StaffBunk");privacy.Add(new{room=id,door=(string)d["id"],bed=(string)q["name"],height=y,screened,firstHit=hit?h.transform.name:"none"});}}}
  var meeting=root.Find("B1_C05_Sector/Equipment");var board=meeting.Find("B1_C05_Conference_PresentationBoard_02");var target=board.position+board.rotation*new Vector3(0,2,.075f);foreach(var chair in plan["placements"].Where(q=>(string)q["room"]=="C05"&&(string)q["model"]=="SF_TaskChair")){var t=meeting.Find((string)chair["name"]);var from=t.position+Vector3.up*1.22f;bool hit=Physics.Linecast(from,target,out var h,~0,QueryTriggerInteraction.Ignore);seats.Add(new{seat=t.name,visible=!hit||h.transform==board||h.transform.IsChildOf(board),firstHit=hit?h.transform.name:"none",distance=Vector3.Distance(from,target)});}
  var result=new{privacy,seats,privacyExposed=privacy.Count(q=>!(bool)q.GetType().GetProperty("screened").GetValue(q)),blockedSeats=seats.Count(q=>!(bool)q.GetType().GetProperty("visible").GetValue(q))};File.WriteAllText(O+"sightlines.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{privacyRays=privacy.Count,result.privacyExposed,meetingSeats=seats.Count,result.blockedSeats};}
}
